/**
 * The font files the map labels are rasterized from, in the order MapLibre
 * should try them.
 *
 * GENERATED by data/scripts/fetch-fonts.sh — do not hand-edit.
 *
 * ⚠️ The ranges are Google's own subset boundaries, copied from the stylesheet
 * it serves, and they are not the obvious ones: `latin` stops at U+00FF and
 * `latin-ext` owns U+0100-02BA. MapLibre takes the first declared face whose
 * range covers a codepoint, so a widened range here would hand a character to a
 * file that does not contain it and the glyph would come from the system font.
 */

export interface LabelFace {
  /** File name under public/fonts/. */
  file: string;
  /** CSS `unicode-range` entries this file is allowed to cover. */
  ranges: string[];
}

